pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {ReentrancyDAO} from "../src/ReentrancyDAO.sol";

contract InvMutTest is Test {
    ReentrancyDAO c;
    function setUp() public { c = new ReentrancyDAO(); }
    function testRegression_property() public {
        address user = address(0x1234);
        vm.deal(user, 1 wei);
        vm.prank(user);
        c.deposit{value: 1 wei}();

        bool ok;
        vm.prank(user);
        try c.withdrawAll() { ok = true; } catch { ok = false; }

        assertTrue(ok == true);
    }
}
